codeExamples.code:
-- Preview the files that would be deleted (non-destructive)
VACUUM events DRY RUN;

-- Apply with the default 7-day (168 hour) retention
VACUUM events;

-- Vacuum by full Unity Catalog path is also supported
VACUUM main.analytics.events;

-- This FAILS by default because 24 hours < 7 day safety threshold
VACUUM events RETAIN 24 HOURS;
-- Error: requested retention is shorter than the safe minimum

-- To allow it, you must explicitly disable the guard (use with extreme care)
SET spark.databricks.delta.retentionDurationCheck.enabled = false;
VACUUM events RETAIN 24 HOURS;

-- Re-enable the guard afterwards
SET spark.databricks.delta.retentionDurationCheck.enabled = true;
